interface.signature:
CREATE TABLE verified_qa ( id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, group_id UUID NOT NULL REFERENCES groups(id) ON DELETE CASCADE, bot_id UUID NOT NULL REFERENCES bots(id) ON DELETE CASCADE, question_text TEXT NOT NULL CHECK(length(question_text) <= 2000), question_embedding VECTOR(768) NOT NULL, answer_text TEXT NOT NULL, source_citations JSONB, approved_by_user_id UUID NOT NULL REFERENCES users(id), approved_at TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW() );
-- Vector index for semantic search CREATE INDEX verified_qa_embedding_idx ON verified_qa USING ivfflat (question_embedding vector_cosine_ops) WITH (lists = 100);
-- Composite indexes for scoped queries CREATE INDEX verified_qa_scope_idx ON verified_qa (tenant_id, group_id, bot_id);
CREATE INDEX verified_qa_tenant_group_idx ON verified_qa (tenant_id, group_id);
-- RLS policy CREATE POLICY verified_qa_isolation ON verified_qa USING (tenant_id = current_setting('app.current_tenant_id')::uuid AND group_id = current_setting('app.current_group_id')::uuid);
